body:
OK, it's a bug at least back to 1.4, likely not in 1.3, the difference between update/insert can be fixed with a patch like this:

```diff
diff --git a/lib/sqlalchemy/sql/crud.py b/lib/sqlalchemy/sql/crud.py
index 48ab721286..95e6d67348 100644
--- a/lib/sqlalchemy/sql/crud.py
+++ b/lib/sqlalchemy/sql/crud.py
@@ -75,14 +75,14 @@ def _get_crud_params(compiler, stmt, compile_state, **kw):
         ]
 
     if compile_state._has_multi_parameters:
-        spd = compile_state._multi_parameters[0]
-        stmt_parameter_tuples = list(spd.items())
+        spd = {_column_as_key(key) for key in compile_state._multi_parameters[0]}
+        stmt_parameter_tuples = list(compile_state._multi_parameters[0].items())
     elif compile_state._ordered_values:
-        spd = compile_state._dict_parameters
+        spd = {_column_as_key(key) for key in compile_state._dict_parameters}
         stmt_parameter_tuples = compile_state._ordered_values
     elif compile_state._dict_parameters:
-        spd = compile_state._dict_parameters
-        stmt_parameter_tuples = list(spd.items())
+        spd = {_column_as_key(key) for key in compile_state._dict_parameters}
+        stmt_parameter_tuples = list(compile_state._dict_parameters.items())
     else:
         stmt_parameter_tuples = spd = None
 
@@ -496,6 +496,7 @@ def _append_param_parameter(
         c, use_table=compile_state.include_table_with_column_exprs
     )
 
+
     if coercions._is_literal(value):
         value = _create_bind_param(
             compiler,

